<script setup lang="ts">
import {ref,reactive,onMounted,watch} from 'vue'
import {UserRound,Bell,Heart,Save,Music2,LogOut} from 'lucide-vue-next'
import {user,profile,invitation,refreshProfile,logout} from '../lib/session'
import {db,fail,friendly} from '../lib/supabase'
import {editableProfile} from '../lib/profile'
import type {Announcement,Rsvp,Song} from '../lib/types'
const emit=defineEmits<{login:[]}>()
const tab=ref('invitation'),busy=ref(false),message=ref(''),error=ref(''),announcements=ref<Announcement[]>([]),songs=ref<Song[]>([])
const form=reactive({full_name:'',alias:'',phone:'',email_updates:false,in_app_updates:true,leaderboard_visible:false})
const rsvp=reactive({attending:true,guests:1,guest_names:'',dietary:'',bus:false})
function populate(){Object.assign(form,editableProfile(profile.value??{full_name:user.value?.user_metadata.full_name??'',alias:user.value?.user_metadata.alias??'',phone:'',email_updates:false,in_app_updates:true,leaderboard_visible:false}))}
async function load(){if(!user.value)return;populate();const [r,a,s]=await Promise.all([db.from('wedding_rsvps').select('*').eq('user_id',user.value.id).maybeSingle(),db.from('wedding_announcements').select('*').eq('published',true).order('created_at',{ascending:false}),db.from('wedding_songs').select('*').eq('user_id',user.value.id).order('created_at',{ascending:false})]);for(const q of [r,a,s])fail(q.error);if(r.data)Object.assign(rsvp,r.data as Rsvp);announcements.value=a.data??[];songs.value=s.data??[]}
async function action(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=friendly(e)}finally{busy.value=false}}
async function saveProfile(){await action(async()=>{if(!user.value)return;const payload=editableProfile(form);const result=profile.value?await db.from('wedding_profiles').update(payload).eq('id',user.value.id):await db.from('wedding_profiles').insert({...payload,id:user.value.id});fail(result.error);await refreshProfile();message.value='Tu perfil y preferencias están guardados.';await load()})}
async function saveRsvp(){await action(async()=>{if(!user.value)return;const {error:e}=await db.from('wedding_rsvps').upsert({user_id:user.value.id,attending:rsvp.attending,guests:rsvp.attending?rsvp.guests:0,guest_names:rsvp.attending?rsvp.guest_names:'',dietary:rsvp.attending?rsvp.dietary:'',bus:rsvp.attending&&rsvp.bus,updated_at:new Date().toISOString()});fail(e);message.value='¡Respuesta guardada! Gracias por ayudarnos a preparar este día.'})}
const labels:Record<string,string>={pending:'Pendiente de revisar',approved:'Aprobada · pendiente de Spotify',added:'Añadida a Spotify',rejected:'No seleccionada'}
watch(()=>user.value?.id,()=>{void load().catch(e=>error.value=friendly(e))});watch(profile,populate);onMounted(()=>{void load().catch(e=>error.value=friendly(e))})
</script>
<template><section id="mi-invitacion" class="section guest-section"><div class="section-heading"><span class="eyebrow">QUEREMOS CONTAR CONTIGO</span><h2>Tu lugar en esta historia</h2><p>Confirma tu asistencia, guarda tus partidas y no te pierdas ningún detalle.</p></div><div v-if="!user" class="guest-welcome"><Heart :size="30"/><h3>Estamos preparando algo muy especial</h3><p>Abre el enlace personal que te enviaron Laura y Javier para activar tu cuenta.</p><button class="btn" @click="emit('login')">Ya tengo cuenta · Entrar <UserRound :size="17"/></button></div><div v-else class="guest-panel"><div class="panel-top"><h3>Hola, {{profile?.full_name.split(' ')[0]||'bienvenido'}}</h3><button class="text-link" @click="action(logout)"><LogOut :size="16"/> Salir</button></div><div class="tabs"><button :class="{active:tab==='invitation'}" @click="tab='invitation'">Mi invitación</button><button :class="{active:tab==='profile'}" @click="tab='profile'"><UserRound :size="15"/> Perfil</button><button :class="{active:tab==='news'}" @click="tab='news';load()"><Bell :size="15"/> Avisos</button><button :class="{active:tab==='songs'}" @click="tab='songs';load()"><Music2 :size="15"/> Canciones</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p><form v-if="tab==='profile'||!profile" class="form-grid" @submit.prevent="saveProfile"><p v-if="!profile" class="full-width notice">Completa tu perfil para guardar canciones y puntuaciones. Los novios podrán habilitar tu confirmación de asistencia.</p><label>Nombre y apellidos<input v-model="form.full_name" required minlength="2" maxlength="100" autocomplete="name"/></label><label>Alias para el juego<input v-model="form.alias" required minlength="2" maxlength="24" autocomplete="nickname"/></label><label>Teléfono opcional<input v-model="form.phone" type="tel" maxlength="30" autocomplete="tel"/></label><label>Correo de tu cuenta<input :value="user.email" disabled/></label><div class="full-width preference-list"><label class="check"><input v-model="form.in_app_updates" type="checkbox"/>Quiero ver los avisos de la boda en mi área privada.</label><label class="check"><input v-model="form.email_updates" type="checkbox"/>Quiero recibir novedades de la boda por correo si se activa ese canal.</label><label class="check"><input v-model="form.leaderboard_visible" type="checkbox"/>Quiero que mi alias y mejor puntuación aparezcan en la clasificación para usuarios registrados.</label><p class="small muted">Puedes cambiar estas preferencias cuando quieras. Los novios usarán tu nombre y datos de contacto para gestionar la boda. Las necesidades de menú solo se comparten con ellos. Para corregir o solicitar la eliminación de tu cuenta, contacta con la pareja.</p></div><button class="btn" :disabled="busy"><Save :size="16"/>{{busy?'Guardando…':'Guardar mi perfil'}}</button></form><template v-else-if="tab==='invitation'"><div v-if="!invitation?.approved" class="empty-state"><Heart/><h3>Ya estás en nuestra lista</h3><p>Los novios revisarán tu registro y habilitarán tu invitación. Mientras tanto, puedes proponer canciones y jugar.</p><button class="btn secondary" @click="action(async()=>{await refreshProfile();message='Invitación actualizada.'})">Actualizar invitación</button></div><form v-else @submit.prevent="saveRsvp" class="form-grid"><p class="full-width">Tu invitación incluye hasta <strong>{{invitation.max_guests}} {{invitation.max_guests===1?'persona':'personas'}}</strong>, contándote a ti.</p><label>¿Nos acompañarás?<select v-model="rsvp.attending"><option :value="true">¡Sí, allí estaré!</option><option :value="false">Esta vez no podré ir</option></select></label><label v-if="rsvp.attending">Número de asistentes<input v-model.number="rsvp.guests" type="number" min="1" :max="invitation.max_guests" required/></label><label v-if="rsvp.attending" class="full-width">Nombres de los asistentes<textarea v-model="rsvp.guest_names" maxlength="1000" placeholder="Incluye tu nombre y el de tus acompañantes" required/></label><label v-if="rsvp.attending" class="full-width">Necesidades de menú opcionales<textarea v-model="rsvp.dietary" maxlength="1000" placeholder="Indica solo lo que debamos tener en cuenta para el menú"/></label><label v-if="rsvp.attending" class="check full-width"><input v-model="rsvp.bus" type="checkbox"/>Me interesa el transporte si se organiza.</label><button class="btn" :disabled="busy">{{busy?'Guardando…':'Confirmar mi respuesta'}}<Heart :size="16"/></button></form></template><div v-else-if="tab==='news'"><p v-if="!announcements.length" class="empty-state">No hay avisos disponibles. Si los has desactivado, puedes volver a activarlos en tu perfil.</p><article v-for="a in announcements" :key="a.id" class="announcement"><span class="eyebrow">{{new Date(a.created_at).toLocaleDateString('es-ES')}}</span><h3>{{a.title}}</h3><p class="preserve">{{a.body}}</p></article></div><div v-else-if="tab==='songs'"><p v-if="!songs.length" class="empty-state">Todavía no has propuesto ninguna canción. ¡La pista te espera!</p><div v-for="s in songs" :key="s.id" class="song-row"><div><b>{{s.title}}</b><p>{{s.artist}}</p></div><span class="badge">{{labels[s.status]}}</span></div></div></div></section></template>
